import {projectDiff} from './agent.mjs';
export class SharedLevel{
 constructor(api){this.api=api;this.token=null;this.revision=0;this.applied=-1;this.pending=0;this.queue=Promise.resolve();this.canUndo=false;this.paused=false;this.lastControl=null;this.epoch=0}
 get connected(){return !!this.token&&!this.paused}
 async request(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(r.status===304)return null;const data=await r.json();if(!r.ok||data.isError)throw Error(data.error||data.content?.[0]?.text||'Agent connection failed.');return data}
 async connect(token){await this.queue;const epoch=++this.epoch;this.paused=false;let room;const starting=this.api.snapshot();if(token){this.token=token;room=await this.request('/api/rooms/'+token)}else{room=await this.request('/api/rooms',{method:'POST',body:JSON.stringify(starting)});if(epoch!==this.epoch)return;this.token=room.token}if(epoch!==this.epoch)return;this.revision=room.revision;this.applied=-1;if(!token&&JSON.stringify(starting)!==JSON.stringify(this.api.snapshot()))await this.push(room.project,this.api.snapshot());else await this.accept(room);clearTimeout(this.timer);this.poll();return this.url()}
 detach(){this.epoch++;this.token=null;this.paused=false;this.incoming=null;this.lastControl=null;clearTimeout(this.timer);clearTimeout(this.previewTimer)}
 url(){return location.origin+'/mcp/'+this.token}
 async accept(room){if(!room)return;const cache=new Map(this.api.snapshot().assets.map(a=>[a.id,a.src]));room.project.assets=room.project.assets.map(a=>({...a,src:a.src||cache.get(a.id)}));this.revision=room.revision;this.canUndo=room.canUndo;if(this.api.busy()||this.pending){this.incoming=room;return}if(await this.api.apply(room.project)===false){this.incoming=room;return}this.applied=room.revision;this.incoming=null;if(room.control&&room.control.id!==this.lastControl){this.lastControl=room.control.id;this.api.setPlay(room.control.playing)}this.api.changed();this.capture()}
 push(before,after){if(!this.connected)return;const diff=projectDiff(before,after);if(!Object.keys(diff).some(k=>Array.isArray(diff[k])?diff[k].length:true))return;this.pending++;this.queue=this.queue.then(async()=>{const room=await this.request('/api/rooms/'+this.token,{method:'PATCH',body:JSON.stringify({diff,knownAssets:after.assets.map(a=>a.id)})});this.revision=room.revision;this.incoming=room}).catch(error=>{this.paused=true;this.api.error(error.message+' Your local edits are kept. Save or reconnect to continue.');}).finally(async()=>{this.pending--;if(!this.pending&&!this.paused&&this.incoming)await this.accept(this.incoming)});return this.queue}
 async poll(){const epoch=this.epoch,token=this.token;if(!token||this.paused)return;try{if(!this.pending&&!this.api.busy()){if(this.incoming)await this.accept(this.incoming);const known=this.api.snapshot().assets.slice(0,100).map(a=>a.id).join(',');const room=await this.request('/api/rooms/'+token+'?revision='+this.applied+'&assets='+encodeURIComponent(known));if(epoch===this.epoch)await this.accept(room)}}catch(error){if(epoch===this.epoch)this.api.error('Agent connection interrupted. Local edits are kept.');}finally{if(epoch===this.epoch)this.timer=setTimeout(()=>this.poll(),1500)}}
 async tool(name,args={}){await this.queue;if(this.paused)throw Error('Reconnect the agent session first.');const result=await this.request('/api/rooms/'+this.token,{method:'POST',body:JSON.stringify({name,arguments:args})});const room=await this.request('/api/rooms/'+this.token);await this.accept(room);return result}
 capture(){if(!this.connected)return;clearTimeout(this.previewTimer);this.previewTimer=setTimeout(async()=>{if(this.api.busy()||this.pending)return;try{const src=await this.api.preview();await this.request('/api/rooms/'+this.token+'/preview',{method:'POST',body:JSON.stringify({src,revision:this.applied})})}catch{}},400)}
 async disconnect(){await this.queue;const token=this.token;await this.request('/api/rooms/'+token,{method:'DELETE'});this.detach();this.api.changed()}
}
